  (* [comment removed for export] *)
  (* [comment removed for export] *)
  [0x909fc; 0x90a50; 0x90a74; 0x90ba4; 0x90cdc; 0x90d70; 0x9154c; 0x9172c; 0x92204; 0x94594; 0x94798; 0x988ac; 0x9926c; 0x99274; 0x9ab08; 0x9ab4c; 0xa6fe0; 0xa701c; 0xa7160; 0xa7168; 0xa7294; 0xa72d4; 0xa72f4; 0xa72fc; 0xa7444; 0xa756c; 0xa7574; 0xa75e8; 0xa7600; 0xa84b4; 0xa84f4; 0xa8508; 0xa8510].

